async function viewSettings(e){const[t,a,s]=await Promise.all([api("/family/members"),api("/ha/info").catch(()=>({url:null})),api("/mail/info").catch(()=>({url:null}))]),n=t.filter(e=>"child"===e.role),i="admin"===ME.role||"adult"===ME.role;e.innerHTML=`<div class="pagehead"><div><h1>Settings</h1><p>Your profile, theme and family pictures.</p></div></div>\n    <div class="card"><h3>Appearance</h3>\n      <p class="muted" style="margin-top:0">Choose how Family Hub looks on this account.</p>\n      <div class="row">${["light","dark","system"].map(e=>`<button class="btn ${(ME.theme||"light")===e?"":"ghost"} small" data-theme="${e}">${THEME_LABELS[e]}</button>`).join("")}</div>\n      <p class="muted" style="margin:16px 0 8px">Language</p>\n      <div class="row">${[["en","🇬🇧 English"],["ro","🇷🇴 Română"]].map(([e,t])=>`<button class="btn ${(ME.lang||"en")===e?"":"ghost"} small" data-lang="${e}">${t}</button>`).join("")}</div>\n    </div>\n    ${"admin"===ME.role?`<details class="card foldcard" style="margin-top:16px"><summary>${"ro"===LANG?"Meniu":"Menu"}</summary><div style="padding-top:12px">\n      <p class="muted" style="margin-top:0">${"ro"===LANG?"Ce pagini apar în meniu, pentru toată familia. O pagină scoasă rămâne în aplicație: o pui înapoi oricând de aici.":"Which pages show in the menu, for the whole family. A page left out stays in the app: put it back here any time."}</p>\n      <div class="row" style="flex-wrap:wrap;gap:8px 16px">\n        ${NAV.filter(([e])=>NAV_HIDEABLE.includes(e)).map(([e,,t])=>`<label style="display:inline-flex;align-items:center;gap:8px;margin:0;font-size:14px;font-weight:500;color:var(--ink)"><input type="checkbox" data-navpage="${e}" ${navHidden().has(e)?"":"checked"} style="width:auto"> ${tr(t)}</label>`).join("")}\n      </div>\n      <button class="btn small" id="navsave" style="margin-top:12px">${"ro"===LANG?"Salvează meniul":"Save the menu"}</button>\n    </div></details>`:""}\n    <details class="card foldcard" style="margin-top:16px"><summary>Notifications on this device</summary><div style="padding-top:12px">\n      <p class="muted" style="margin-top:0">Get alerts (RCA, ITP, acte, birthdays…) as push notifications on this phone/computer even when the site is closed. Tip: on a phone, first use "Add to Home Screen" to install the app.</p>\n      <div class="row"><button class="btn small" id="pushbtn">…</button><button class="btn ghost small" id="pushtest" hidden>Send a test</button></div>\n      <p class="muted" style="margin:16px 0 8px">Which alerts do you want?</p>\n      <div class="row" style="flex-wrap:wrap;gap:8px 16px">\n        ${[["vehicles","Vehicles (RCA, ITP, rovinietă…)"],["property","Property insurance"],["tenant","Tenant & rent"],["documents","Documents (acte)"],["birthdays","Birthdays"],["bills","ro"===LANG?"Facturi cu notificare pornită":"Bills with an alert turned on"]].map(([e,t])=>`<label style="display:inline-flex;align-items:center;gap:8px;margin:0;font-size:14px;font-weight:500;color:var(--ink)"><input type="checkbox" data-ngroup="${e}" ${String(ME.notif_muted||"").split(",").includes(e)?"":"checked"} style="width:auto"> ${t}</label>`).join("")}\n      </div>\n      <p class="muted" style="margin:16px 0 8px">Quiet hours (push notifications wait until morning)</p>\n      <div class="row">\n        <select id="qstart" style="width:110px"><option value="">Off</option>${Array.from({length:24},(e,t)=>`<option value="${t}" ${ME.quiet_start===t?"selected":""}>${String(t).padStart(2,"0")}:00</option>`).join("")}</select>\n        <span class="muted">–</span>\n        <select id="qend" style="width:110px"><option value="">Off</option>${Array.from({length:24},(e,t)=>`<option value="${t}" ${ME.quiet_end===t?"selected":""}>${String(t).padStart(2,"0")}:00</option>`).join("")}</select>\n        <button class="btn small" id="notifsave">Save alert settings</button>\n      </div>\n      <p class="muted" style="margin:8px 0 0">Alert choices are yours alone — every family member picks their own.</p>\n    </div></details>\n    <div class="card" style="margin-top:16px"><h3>Your profile</h3>\n      <div class="row" style="gap:16px;align-items:center">${avatarHtml(ME,"avatar-lg")}\n        <div class="row">\n          ${"child"!==ME.role?`<label class="btn ghost small" style="display:inline-block">Upload picture<input type="file" data-avatar="${ME.id}" data-self accept="image/*" hidden></label>`:""}\n          ${ME.avatar?`<button class="btn danger small" data-avadel="${ME.id}" data-self>Remove</button>`:""}\n        </div></div>\n      ${"child"!==ME.role?`<form id="nameform" class="formgrid" style="margin-top:12px;max-width:560px">\n        <div><label>Display name</label><input name="name" value="${esc(ME.name)}" required></div>\n        <div><label>Birthday</label><input name="birthday" type="date" value="${esc(ME.birthday||"")}"></div>\n        <div><label>Phone number</label><input name="phone" type="tel" value="${esc(ME.phone||"")}" placeholder="07xx xxx xxx"></div>\n        <button class="btn small">Save profile</button></form>`:""}\n    </div>\n    ${ME.email?'<div class="card" style="margin-top:16px"><h3>Password</h3>\n      <p class="muted" style="margin-top:0">Changing it signs you out on every other device.</p>\n      <button class="btn small" id="pwbtn">Change password</button>\n    </div>':""}\n    ${i&&n.length?`<div class="card" style="margin-top:16px"><h3>Children's pictures</h3>\n      <div class="row" style="gap:24px;flex-wrap:wrap">${n.map(e=>`<div style="text-align:center">${avatarHtml(e,"avatar-lg")}\n        <div style="margin-top:8px"><b>${esc(e.name)}</b></div>\n        <div class="row" style="justify-content:center;margin-top:4px">\n          <label class="btn ghost small" style="display:inline-block">Upload<input type="file" data-avatar="${e.id}" accept="image/*" hidden></label>\n          ${e.avatar?`<button class="btn danger small" data-avadel="${e.id}">✕</button>`:""}</div></div>`).join("")}</div></div>`:""}\n    ${"admin"===ME.role?`<div class="card" style="margin-top:16px"><h3>${tr("Invoices by email")}</h3>\n      <p class="muted" style="margin-top:0">${tr("Forward an invoice to this address and it lands in Bills as a draft, with the amount read out of it. Nothing is counted until you accept it.")}</p>\n      ${s.url?`<div class="row" style="gap:8px;flex-wrap:wrap;align-items:center">\n            <code class="tokenline">${esc(s.url)}</code>\n            <button class="btn ghost small" data-copy="${esc(s.url)}">${tr("Copy")}</button>\n            <button class="btn ghost small" id="mailrotate">${tr("New address")}</button></div>`:`<button class="btn small" id="mailgen">${tr("Create the address")}</button>`}</div>\n    <div class="card" style="margin-top:16px"><h3>${tr("House dashboard")}</h3>\n      <p class="muted" style="margin-top:0">${tr("A read-only address Home Assistant can read to show these numbers on a wall panel. It gives out figures only — no names, no notes, no addresses — and it cannot change anything here.")}</p>\n      ${a.url?`<div class="row" style="gap:8px;flex-wrap:wrap;align-items:center">\n            <code class="tokenline">${esc(a.url)}</code>\n            <button class="btn ghost small" data-copy="${esc(a.url)}">${tr("Copy")}</button>\n            <button class="btn ghost small" id="harotate">${tr("New address")}</button></div>`:`<button class="btn small" id="hagen">${tr("Create the address")}</button>`}</div>\n    <div class="card" style="margin-top:16px"><h3>${tr("Backup")}</h3>\n      <p class="muted" style="margin-top:0">${tr("A compressed copy of the whole database, taken cleanly while the app keeps running. Scans and invoices are not in it — those live in the uploads folder.")}</p>\n      <button class="btn small" id="dlbackup">${tr("Download backup")}</button></div>`:""}`,$("#navsave")?.addEventListener("click",async t=>{const a=[...e.querySelectorAll("[data-navpage]")].filter(e=>!e.checked).map(e=>e.dataset.navpage);t.target.disabled=!0;try{await api("/family",{method:"PATCH",body:{nav_hidden:a}});const e=await api("/me");FAMILY=e.family,toast("ro"===LANG?"Meniul e salvat":"Menu saved","success"),render()}catch(e){t.target.disabled=!1,toast(e.message)}}),e.querySelectorAll("[data-theme]").forEach(e=>e.onclick=async()=>{try{const t=await api("/settings",{method:"POST",body:{theme:e.dataset.theme}});ME={...ME,...t},applyTheme(),render()}catch(e){toast(e.message)}}),e.querySelectorAll("[data-lang]").forEach(e=>e.onclick=async()=>{try{const t=await api("/settings",{method:"POST",body:{lang:e.dataset.lang}});ME={...ME,...t},applyLang(),render()}catch(e){toast(e.message)}});const l=async()=>{try{await api("/mail/token",{method:"POST"}),toast(tr("Address ready"),"success"),viewSettings(e)}catch(e){toast(e.message)}};$("#mailgen")?.addEventListener("click",l),$("#mailrotate")?.addEventListener("click",async()=>{await confirmDestroy({question:"ro"===LANG?"Generezi o adresă nouă pentru facturi?":"Generate a new invoice address?",detail:"ro"===LANG?"Adresa actuală nu mai primește nimic, iar regulile de redirecționare trebuie schimbate.":"The current address stops receiving, and forwarding rules must be updated.",verb:"ro"===LANG?"Generează adresă nouă":"Generate new address"})&&await l()});const o=async()=>{try{await api("/ha/token",{method:"POST"}),toast(tr("Address ready"),"success"),viewSettings(e)}catch(e){toast(e.message)}};$("#hagen")?.addEventListener("click",o),$("#harotate")?.addEventListener("click",async()=>{await confirmDestroy({question:"ro"===LANG?"Generezi o adresă nouă pentru Home Assistant?":"Generate a new Home Assistant address?",detail:"ro"===LANG?"Adresa actuală nu mai merge; senzorul din Home Assistant trebuie actualizat.":"The current address stops working; the Home Assistant sensor must be updated.",verb:"ro"===LANG?"Generează adresă nouă":"Generate new address"})&&await o()}),e.querySelectorAll("[data-copy]").forEach(e=>e.onclick=()=>copyText(e.dataset.copy)),setupPushCard(),$("#notifsave")?.addEventListener("click",async()=>{const t=[...e.querySelectorAll("[data-ngroup]")].filter(e=>!e.checked).map(e=>e.dataset.ngroup),a=$("#qstart").value,s=$("#qend").value,n={notif_muted:t,quiet_start:""===a||""===s?null:Number(a),quiet_end:""===a||""===s?null:Number(s)};try{const e=await api("/settings",{method:"POST",body:n});ME={...ME,...e},toast("Saved"),pollNotifications()}catch(e){toast(e.message)}}),$("#dlbackup")?.addEventListener("click",async e=>{const t=e.target;t.disabled=!0;try{const e=await fetch("/api/backup",{credentials:"same-origin"});if(!e.ok)throw new Error((await e.json().catch(()=>({}))).error||"Request failed");const t=await e.blob(),a=Object.assign(document.createElement("a"),{href:URL.createObjectURL(t),download:`familyhub-${today()}.db.gz`});document.body.appendChild(a),a.click(),a.remove(),setTimeout(()=>URL.revokeObjectURL(a.href),1e4),toast(tr("Backup downloaded"),"success")}catch(e){toast(e.message,"error")}finally{t.disabled=!1}}),$("#pwbtn")?.addEventListener("click",()=>passwordChangeModal()),$("#nameform")?.addEventListener("submit",async e=>{e.preventDefault();try{const t=await api("/settings",{method:"POST",body:Object.fromEntries(new FormData(e.target))});ME={...ME,...t},toast("Saved"),render()}catch(e){toast(e.message)}}),e.querySelectorAll("[data-avatar]").forEach(t=>t.onchange=async()=>{if(!t.files[0])return;const a=new FormData;a.append("file",t.files[0]);try{if(await api(`/users/${t.dataset.avatar}/avatar`,{method:"POST",body:a}),void 0!==t.dataset.self){const e=await api("/me");ME=e.user,render()}else viewSettings(e);toast("Picture updated")}catch(e){toast(e.message)}}),e.querySelectorAll("[data-avadel]").forEach(t=>t.onclick=async()=>{try{if(await api(`/users/${t.dataset.avadel}/avatar`,{method:"DELETE"}),void 0!==t.dataset.self){const e=await api("/me");ME=e.user,render()}else viewSettings(e);toast("Removed")}catch(e){toast(e.message)}})}